-- Wygenerowano z database/zrodlo_slowa.sql.
-- Nie edytuj ręcznie; użyj scripts/dev/convert_mysql_schema_to_postgresql.php.
-- Baseline zachowuje dotychczasowy globalny łańcuch księgi. Jego zmiana nie jest
-- częścią migracji PostgreSQL i wymaga osobnego uzgodnienia sald.

SET client_encoding = 'UTF8';
SET TIME ZONE 'UTC';
SET lock_timeout = '10s';
SET statement_timeout = '120s';

BEGIN;

CREATE TABLE "activity_bonus_notifications" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "activity_type" varchar(50) NOT NULL,
    "amount_minor" bigint NOT NULL DEFAULT '0',
    "points_amount" integer NOT NULL DEFAULT '0',
    "message" varchar(255) NOT NULL,
    "title_key" varchar(160) DEFAULT NULL,
    "message_key" varchar(160) DEFAULT NULL,
    "description_key" varchar(160) DEFAULT NULL,
    "reference_type" varchar(50) DEFAULT NULL,
    "reference_id" bigint DEFAULT NULL,
    "seen_at" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "activity_reward_logs" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "activity_type" varchar(50) NOT NULL,
    "reference_type" varchar(50) DEFAULT NULL,
    "reference_id" bigint DEFAULT NULL,
    "points_amount" integer NOT NULL,
    "amount_minor" bigint NOT NULL DEFAULT '0',
    "wallet_transaction_id" bigint DEFAULT NULL,
    "live_message" varchar(255) DEFAULT NULL,
    "title_key" varchar(160) DEFAULT NULL,
    "message_key" varchar(160) DEFAULT NULL,
    "description_key" varchar(160) DEFAULT NULL,
    "awarded_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "activity_reward_rules" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "activity_type" varchar(50) NOT NULL,
    "points_amount" integer NOT NULL DEFAULT '0',
    "amount_minor" bigint NOT NULL DEFAULT '0',
    "label" varchar(120) DEFAULT NULL,
    "live_message_template" varchar(255) DEFAULT NULL,
    "title_key" varchar(160) DEFAULT NULL,
    "message_key" varchar(160) DEFAULT NULL,
    "description_key" varchar(160) DEFAULT NULL,
    "daily_limit" integer NOT NULL DEFAULT '0',
    "is_active" smallint NOT NULL DEFAULT '1',
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_activity_reward_rules_activity_type" UNIQUE ("activity_type")
);

CREATE TABLE "ad_clicks" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "campaign_id" bigint NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "campaign_event_id" bigint NOT NULL,
    "clicked_at" timestamp without time zone NOT NULL,
    "target_url" varchar(500) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "ad_views" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "campaign_id" bigint NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "campaign_event_id" bigint NOT NULL,
    "viewed_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "admin_audit_logs" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint DEFAULT NULL,
    "action" varchar(120) NOT NULL,
    "payload" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "ai_budget_periods" (
    "period_start" date NOT NULL,
    "budget_minor" bigint NOT NULL,
    "reserved_minor" bigint NOT NULL DEFAULT '0',
    "spent_minor" bigint NOT NULL DEFAULT '0',
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "updated_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("period_start")
);

CREATE TABLE "ai_job_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "ai_job_id" bigint NOT NULL,
    "event_type" varchar(64) NOT NULL,
    "actor_user_id" bigint DEFAULT NULL,
    "status_from" varchar(32) DEFAULT NULL,
    "status_to" varchar(32) DEFAULT NULL,
    "message" varchar(255) DEFAULT NULL,
    "payload_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "ai_jobs" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "public_id" varchar(64) NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "article_id" bigint DEFAULT NULL,
    "translation_id" bigint DEFAULT NULL,
    "type" varchar(64) NOT NULL,
    "provider" varchar(32) NOT NULL DEFAULT 'openai',
    "model" varchar(128) DEFAULT NULL,
    "status" varchar(32) NOT NULL DEFAULT 'draft',
    "prompt_code" varchar(96) DEFAULT NULL,
    "prompt_version" varchar(32) DEFAULT NULL,
    "input_hash" varchar(128) DEFAULT NULL,
    "input_json" jsonb DEFAULT NULL,
    "output_json" jsonb DEFAULT NULL,
    "error_message" text,
    "tokens_input" integer DEFAULT NULL,
    "tokens_output" integer DEFAULT NULL,
    "estimated_cost_minor" bigint NOT NULL DEFAULT '0',
    "actual_cost_minor" bigint NOT NULL DEFAULT '0',
    "budget_period" date DEFAULT NULL,
    "budget_status" text NOT NULL DEFAULT 'none' CHECK ("budget_status" IN ('none','reserved','spent','released')),
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "queued_at" timestamp without time zone DEFAULT NULL,
    "started_at" timestamp without time zone DEFAULT NULL,
    "completed_at" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_ai_jobs_public_id" UNIQUE ("public_id")
);

CREATE TABLE "ai_prompt_templates" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(96) NOT NULL,
    "name" varchar(160) NOT NULL,
    "name_key" varchar(160) DEFAULT NULL,
    "task_type" varchar(64) NOT NULL,
    "version" varchar(32) NOT NULL DEFAULT 'v1',
    "provider" varchar(32) NOT NULL DEFAULT 'openai',
    "model" varchar(128) DEFAULT NULL,
    "system_prompt" text NOT NULL,
    "user_template" text NOT NULL,
    "output_schema_json" jsonb DEFAULT NULL,
    "is_active" smallint NOT NULL DEFAULT '1',
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_ai_prompt_templates_code" UNIQUE ("code")
);

CREATE TABLE "article_access_grants" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "article_id" bigint NOT NULL,
    "payment_id" bigint DEFAULT NULL,
    "status" text NOT NULL DEFAULT 'active' CHECK ("status" IN ('active','revoked','expired')),
    "revoked_at" timestamp without time zone DEFAULT NULL,
    "source" text NOT NULL DEFAULT 'payment' CHECK ("source" IN ('wallet','payment','legacy_edd','admin')),
    "granted_at" timestamp without time zone NOT NULL,
    "expires_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_article_access_grants_uq_aag_user_article" UNIQUE ("user_id","article_id")
);

CREATE TABLE "article_categories" (
    "article_id" bigint NOT NULL,
    "category_id" bigint NOT NULL,
    PRIMARY KEY ("article_id","category_id")
);

CREATE TABLE "article_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "article_id" bigint NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "event" varchar(80) NOT NULL,
    "payload_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "article_purchases" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "article_id" bigint NOT NULL,
    "buyer_user_id" bigint NOT NULL,
    "author_user_id" bigint NOT NULL,
    "payment_id" bigint DEFAULT NULL,
    "total_amount_minor" bigint NOT NULL,
    "author_amount_minor" bigint NOT NULL,
    "platform_amount_minor" bigint NOT NULL,
    "author_share_percent" decimal(5,2) NOT NULL DEFAULT '70.00',
    "platform_share_percent" decimal(5,2) NOT NULL DEFAULT '30.00',
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "status" text NOT NULL DEFAULT 'paid' CHECK ("status" IN ('paid','refunded','cancelled')),
    "access_granted_until" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_article_purchases_uq_article_purchase_buyer_article" UNIQUE ("buyer_user_id","article_id")
);

CREATE TABLE "article_reads" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "article_id" bigint NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "ip_hash" char(64) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "article_supports" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "article_id" bigint NOT NULL,
    "reader_id" bigint NOT NULL,
    "author_id" bigint NOT NULL,
    "payment_id" bigint NOT NULL,
    "amount_minor" bigint NOT NULL,
    "note" text,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "article_translations" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "article_id" bigint NOT NULL,
    "language" varchar(10) NOT NULL DEFAULT 'en',
    "source_language" varchar(16) NOT NULL DEFAULT 'pl',
    "target_language" varchar(16) NOT NULL,
    "title" varchar(255) NOT NULL,
    "lead" text,
    "body" text NOT NULL,
    "seo_title" varchar(255) DEFAULT NULL,
    "seo_description" text,
    "seo_keywords" text,
    "slug" varchar(255) DEFAULT NULL,
    "status" varchar(50) NOT NULL DEFAULT 'draft',
    "translation_instructions" text,
    "ai_provider" varchar(100) DEFAULT NULL,
    "ai_model" varchar(100) DEFAULT NULL,
    "provider" varchar(32) DEFAULT NULL,
    "ai_job_id" bigint DEFAULT NULL,
    "created_by" bigint DEFAULT NULL,
    "updated_by" bigint DEFAULT NULL,
    "reviewed_by" bigint DEFAULT NULL,
    "published_by" bigint DEFAULT NULL,
    "published_at" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    "reviewed_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_article_translations_uniq_article_translation_lang" UNIQUE ("article_id","target_language")
);

CREATE TABLE "article_translation_versions" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "translation_id" bigint NOT NULL,
    "version_no" bigint NOT NULL,
    "title" varchar(255) NOT NULL,
    "lead" text,
    "body" text NOT NULL,
    "seo_title" varchar(255) DEFAULT NULL,
    "seo_description" text,
    "seo_keywords" text,
    "slug" varchar(255) DEFAULT NULL,
    "status" varchar(50) NOT NULL,
    "translation_instructions" text,
    "changed_by" bigint DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_article_translation_versions_uniq_article_translati_f65fc221" UNIQUE ("translation_id","version_no")
);

CREATE TABLE "article_versions" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "article_id" bigint NOT NULL,
    "title" varchar(255) NOT NULL,
    "lead" text,
    "body" text NOT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "articles" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "legacy_source" varchar(40) DEFAULT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "author_id" bigint NOT NULL,
    "title" varchar(255) NOT NULL,
    "slug" varchar(255) NOT NULL,
    "lead" text,
    "body" text NOT NULL,
    "status" text NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft','submitted','review','approved','published','rejected','archived')),
    "access_mode" text NOT NULL DEFAULT 'free' CHECK ("access_mode" IN ('free','paid')),
    "price_minor" bigint NOT NULL DEFAULT '0',
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "is_premium" smallint NOT NULL DEFAULT '0',
    "is_unique" smallint NOT NULL DEFAULT '0',
    "pricing_status" text NOT NULL DEFAULT 'not_priced' CHECK ("pricing_status" IN ('not_priced','priced','free','blocked')),
    "author_share_percent" decimal(5,2) NOT NULL DEFAULT '70.00',
    "platform_share_percent" decimal(5,2) NOT NULL DEFAULT '30.00',
    "editor_valuation_note" text,
    "article_label" varchar(50) DEFAULT NULL,
    "valued_by_admin_id" bigint DEFAULT NULL,
    "valued_at" timestamp without time zone DEFAULT NULL,
    "published_at" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone NOT NULL,
    "source_language" varchar(10) NOT NULL DEFAULT 'pl',
    "display_order" integer NOT NULL DEFAULT '0',
    "editorial_weight" integer NOT NULL DEFAULT '0',
    "is_featured" smallint NOT NULL DEFAULT '0',
    "revision_of_article_id" bigint DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "auth_login_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint DEFAULT NULL,
    "email" varchar(255) DEFAULT NULL,
    "result" varchar(32) NOT NULL,
    "ip_hash" varchar(128) DEFAULT NULL,
    "user_agent_hash" varchar(128) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "campaign_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "campaign_id" bigint NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "event_type" text NOT NULL CHECK ("event_type" IN ('view','click','sponsored_read','ppv_purchase','live_join','survey_completed')),
    "event_date" date NOT NULL,
    "cost_minor" bigint NOT NULL DEFAULT '0',
    "reward_minor" bigint NOT NULL DEFAULT '0',
    "ip_hash" char(64) DEFAULT NULL,
    "user_agent" varchar(255) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "watch_seconds" integer NOT NULL DEFAULT '0',
    "is_rewarded" smallint NOT NULL DEFAULT '1',
    "fraud_risk_score" integer NOT NULL DEFAULT '0',
    "fraud_status" text NOT NULL DEFAULT 'normal' CHECK ("fraud_status" IN ('normal','observe','suspect','hold_payout')),
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_campaign_events_uq_campaign_user_daily_event" UNIQUE ("campaign_id","user_id","event_type","event_date")
);

CREATE TABLE "campaigns" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "client_name" varchar(180) DEFAULT NULL,
    "name" varchar(220) NOT NULL,
    "type" text NOT NULL DEFAULT 'display_ad' CHECK ("type" IN ('ad_click','display_ad','sponsored_article','ad_view','ppv','live','survey_ad')),
    "description" text,
    "target_url" varchar(500) DEFAULT NULL,
    "budget_minor" bigint NOT NULL DEFAULT '0',
    "cost_per_view_minor" bigint NOT NULL DEFAULT '0',
    "cost_per_click_minor" bigint NOT NULL DEFAULT '0',
    "cost_per_completed_survey_minor" bigint NOT NULL DEFAULT '0',
    "reward_for_user_minor" bigint NOT NULL DEFAULT '0',
    "status" text NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft','active','paused','closed')),
    "starts_at" timestamp without time zone DEFAULT NULL,
    "ends_at" timestamp without time zone DEFAULT NULL,
    "created_by_admin_id" bigint DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "categories" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "legacy_source" varchar(40) DEFAULT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "name" varchar(190) NOT NULL,
    "slug" varchar(190) NOT NULL,
    "type" varchar(40) NOT NULL DEFAULT 'category',
    "created_at" timestamp without time zone NOT NULL,
    "show_in_menu" smallint NOT NULL DEFAULT '1',
    "menu_order" integer NOT NULL DEFAULT '100',
    "is_active" smallint NOT NULL DEFAULT '1',
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_categories_uq_categories_slug" UNIQUE ("slug")
);

CREATE TABLE "category_translations" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "category_id" bigint NOT NULL,
    "language" varchar(5) NOT NULL,
    "name" varchar(190) NOT NULL,
    "slug" varchar(190) NOT NULL,
    "description" text,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_category_translations_uq_category_language" UNIQUE ("category_id","language")
);

CREATE TABLE "donation_campaigns" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "legacy_id" bigint DEFAULT NULL,
    "name" varchar(190) NOT NULL,
    "slug" varchar(190) NOT NULL,
    "description" text,
    "target_amount_minor" bigint NOT NULL DEFAULT '0',
    "current_amount_minor" bigint NOT NULL DEFAULT '0',
    "active" smallint NOT NULL DEFAULT '1',
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_donation_campaigns_uq_donation_campaign_slug" UNIQUE ("slug")
);

CREATE TABLE "donations" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "payment_id" bigint NOT NULL,
    "campaign_id" bigint DEFAULT NULL,
    "campaign" varchar(190) NOT NULL,
    "target_amount_minor" bigint DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "email_verification_tokens" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "token_hash" varchar(128) NOT NULL,
    "expires_at" timestamp without time zone NOT NULL,
    "used_at" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "finance_balance_reports" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "run_id" bigint DEFAULT NULL,
    "user_id" bigint NOT NULL,
    "legacy_wallet_id" bigint DEFAULT NULL,
    "legacy_points" bigint NOT NULL DEFAULT '0',
    "imported_points" bigint NOT NULL DEFAULT '0',
    "diff_points" bigint NOT NULL DEFAULT '0',
    "legacy_amount_minor" bigint NOT NULL DEFAULT '0',
    "imported_available_minor" bigint NOT NULL DEFAULT '0',
    "diff_minor" bigint NOT NULL DEFAULT '0',
    "status" text NOT NULL DEFAULT 'ok' CHECK ("status" IN ('ok','adjusted','missing_snapshot','error')),
    "note" varchar(255) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "finance_import_errors" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "run_id" bigint NOT NULL,
    "source_table" varchar(120) NOT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "message" text NOT NULL,
    "payload_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "finance_import_runs" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "source" varchar(80) NOT NULL,
    "status" text NOT NULL DEFAULT 'started' CHECK ("status" IN ('started','finished','failed')),
    "summary_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "finished_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "finance_legacy_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "run_id" bigint DEFAULT NULL,
    "source_table" varchar(120) NOT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "ref_transaction_id" bigint DEFAULT NULL,
    "event_type" varchar(80) DEFAULT NULL,
    "status" varchar(80) DEFAULT NULL,
    "occurred_at" timestamp without time zone DEFAULT NULL,
    "payload_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_finance_legacy_events_uq_legacy_event" UNIQUE ("source_table","legacy_id")
);

CREATE TABLE "finance_legacy_wallet_snapshots" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "run_id" bigint DEFAULT NULL,
    "user_id" bigint NOT NULL,
    "legacy_wallet_id" bigint NOT NULL,
    "legacy_points" bigint NOT NULL,
    "legacy_amount_minor" bigint NOT NULL,
    "status" varchar(40) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_finance_legacy_wallet_snapshots_uq_legacy_wallet_snapshot" UNIQUE ("legacy_wallet_id")
);

CREATE TABLE "financial_ledger_head" (
    "id" smallint NOT NULL,
    "last_transaction_id" bigint DEFAULT NULL,
    "last_entry_hash" char(64) NOT NULL,
    "hash_version" integer NOT NULL DEFAULT '2',
    "updated_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "financial_approvals" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "operation_type" varchar(50) NOT NULL,
    "operation_payload" jsonb NOT NULL,
    "amount" bigint NOT NULL,
    "currency" char(3) NOT NULL,
    "wallet_id" bigint NOT NULL,
    "user_id" bigint NOT NULL,
    "requested_by" bigint NOT NULL,
    "requested_role" varchar(50) NOT NULL,
    "approved_by" bigint DEFAULT NULL,
    "approved_role" varchar(50) DEFAULT NULL,
    "status" text NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected','cancelled','executed','failed')),
    "reason" text,
    "admin_note" text,
    "reject_reason" text,
    "created_at" timestamp without time zone NOT NULL,
    "approved_at" timestamp without time zone DEFAULT NULL,
    "rejected_at" timestamp without time zone DEFAULT NULL,
    "executed_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "financial_audit_log" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "wallet_id" bigint NOT NULL,
    "user_id" bigint NOT NULL,
    "action" varchar(50) NOT NULL,
    "actor_id" bigint NOT NULL,
    "actor_role" varchar(50) NOT NULL,
    "amount" bigint NOT NULL,
    "before_json" jsonb DEFAULT NULL,
    "after_json" jsonb DEFAULT NULL,
    "context_json" jsonb DEFAULT NULL,
    "ip_address" varchar(45) DEFAULT NULL,
    "user_agent" varchar(255) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "fraud_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint DEFAULT NULL,
    "event_type" varchar(80) NOT NULL,
    "reference_type" varchar(80) DEFAULT NULL,
    "reference_id" bigint DEFAULT NULL,
    "risk_score" integer NOT NULL DEFAULT '0',
    "status" text NOT NULL DEFAULT 'normal' CHECK ("status" IN ('normal','observe','suspect','hold_payout')),
    "reasons_json" jsonb DEFAULT NULL,
    "ip_hash" char(64) DEFAULT NULL,
    "user_agent_hash" char(64) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "legacy_edd_product_map" (
    "edd_product_id" bigint NOT NULL,
    "target_type" text NOT NULL CHECK ("target_type" IN ('article','wallet_package','donation','donation_campaign')),
    "target_id" bigint DEFAULT NULL,
    "confidence" integer DEFAULT '100',
    "note" text,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("edd_product_id")
);

CREATE TABLE "live_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "campaign_id" bigint DEFAULT NULL,
    "title" varchar(220) NOT NULL,
    "description" text,
    "status" text NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft','scheduled','live','ended')),
    "starts_at" timestamp without time zone DEFAULT NULL,
    "ends_at" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "mail_queue" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint DEFAULT NULL,
    "email" varchar(190) NOT NULL,
    "subject" varchar(255) NOT NULL,
    "body" text NOT NULL,
    "idempotency_key" varchar(190) NOT NULL,
    "status" text NOT NULL DEFAULT 'queued' CHECK ("status" IN ('queued','sending','retry','sent','failed','dead_letter','cancelled')),
    "attempts" bigint NOT NULL DEFAULT '0',
    "max_attempts" bigint NOT NULL DEFAULT '5',
    "available_at" timestamp without time zone NOT NULL,
    "locked_at" timestamp without time zone DEFAULT NULL,
    "locked_by" varchar(100) DEFAULT NULL,
    "error" text,
    "message_id" varchar(255) DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone NOT NULL,
    "sent_at" timestamp without time zone DEFAULT NULL,
    "failed_at" timestamp without time zone DEFAULT NULL,
    "dead_lettered_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_mail_queue_idempotency" UNIQUE ("idempotency_key")
);

CREATE TABLE "background_jobs" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "public_id" varchar(36) NOT NULL,
    "queue_name" varchar(80) NOT NULL,
    "job_type" varchar(100) NOT NULL,
    "status" text NOT NULL DEFAULT 'queued' CHECK ("status" IN ('queued','running','retry','completed','dead_letter','rejected','cancelled')),
    "priority" integer NOT NULL DEFAULT '0',
    "payload_json" jsonb NOT NULL,
    "result_json" jsonb DEFAULT NULL,
    "idempotency_key" varchar(190) NOT NULL,
    "actor_user_id" bigint DEFAULT NULL,
    "required_permission" varchar(100) DEFAULT NULL,
    "request_id" varchar(100) DEFAULT NULL,
    "actor_ip" varchar(64) DEFAULT NULL,
    "retry_policy" text NOT NULL DEFAULT 'automatic' CHECK ("retry_policy" IN ('automatic','manual')),
    "attempts" integer NOT NULL DEFAULT '0' CHECK ("attempts" >= 0),
    "max_attempts" integer NOT NULL DEFAULT '5' CHECK ("max_attempts" BETWEEN 1 AND 20),
    "available_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lease_expires_at" timestamp without time zone DEFAULT NULL,
    "locked_by" varchar(100) DEFAULT NULL,
    "last_error" text,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "started_at" timestamp without time zone DEFAULT NULL,
    "completed_at" timestamp without time zone DEFAULT NULL,
    "dead_lettered_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_background_jobs_public_id" UNIQUE ("public_id"),
    CONSTRAINT "uq_background_jobs_idempotency" UNIQUE ("queue_name","idempotency_key")
);

CREATE TABLE "background_job_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "background_job_id" bigint NOT NULL,
    "event_type" varchar(50) NOT NULL,
    "from_status" varchar(24) DEFAULT NULL,
    "to_status" varchar(24) NOT NULL,
    "worker_id" varchar(100) DEFAULT NULL,
    "details_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE "scheduler_runs" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "task_name" varchar(100) NOT NULL,
    "scheduled_for" timestamp without time zone NOT NULL,
    "status" text NOT NULL CHECK ("status" IN ('running','completed','failed')),
    "result_json" jsonb DEFAULT NULL,
    "error" text,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "completed_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_scheduler_runs_slot" UNIQUE ("task_name","scheduled_for")
);

CREATE TABLE "main_banner_translations" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
