    "event_type" varchar(80) NOT NULL,
    "payload_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "payment_gateway_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "provider" varchar(32) NOT NULL,
    "event_id" varchar(255) NOT NULL,
    "event_type" varchar(128) NOT NULL,
    "payment_order_id" bigint DEFAULT NULL,
    "stripe_session_id" varchar(255) DEFAULT NULL,
    "stripe_payment_intent_id" varchar(255) DEFAULT NULL,
    "received_at" timestamp without time zone NOT NULL,
    "processed_at" timestamp without time zone DEFAULT NULL,
    "processing_status" varchar(32) NOT NULL DEFAULT 'received',
    "payload_json" jsonb DEFAULT NULL,
    "error_message" text,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_payment_gateway_events_uniq_provider_event" UNIQUE ("provider","event_id")
);

CREATE TABLE "payment_items" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "payment_id" bigint NOT NULL,
    "legacy_source" varchar(80) DEFAULT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "item_type" varchar(80) NOT NULL,
    "item_id" bigint DEFAULT NULL,
    "title" varchar(255) NOT NULL,
    "quantity" integer NOT NULL DEFAULT '1',
    "amount_minor" bigint NOT NULL,
    "raw_json" jsonb DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "payment_orders" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "public_id" varchar(64) NOT NULL,
    "user_id" bigint NOT NULL,
    "provider" varchar(32) NOT NULL,
    "method" varchar(32) DEFAULT NULL,
    "type" varchar(64) NOT NULL,
    "status" varchar(32) NOT NULL,
    "amount_minor" bigint NOT NULL,
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "topup_package_id" bigint DEFAULT NULL,
    "stripe_session_id" varchar(255) DEFAULT NULL,
    "stripe_payment_intent_id" varchar(255) DEFAULT NULL,
    "idempotency_key" varchar(128) NOT NULL,
    "credited_at" timestamp without time zone DEFAULT NULL,
    "expires_at" timestamp without time zone DEFAULT NULL,
    "metadata_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_payment_orders_public_id" UNIQUE ("public_id"),
    CONSTRAINT "uq_payment_orders_idempotency_key" UNIQUE ("idempotency_key")
);

CREATE TABLE "payment_webhook_events" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
