    "external_id" varchar(190) DEFAULT NULL,
    "event_type" varchar(120) NOT NULL,
    "payload_json" jsonb DEFAULT NULL,
    "processed_at" timestamp without time zone DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_payment_webhook_events_uq_payment_webhook_event" UNIQUE ("provider","external_id","event_type")
);

CREATE TABLE "payments" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "legacy_source" varchar(80) DEFAULT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "user_id" bigint DEFAULT NULL,
    "provider" varchar(60) NOT NULL,
    "provider_status" varchar(80) DEFAULT NULL,
    "type" text NOT NULL CHECK ("type" IN ('donation','wallet_topup','article_payment')),
    "status" text NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending','paid','failed','refunded','cancelled')),
    "amount_minor" bigint NOT NULL,
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "payer_email" varchar(190) DEFAULT NULL,
    "external_id" varchar(190) DEFAULT NULL,
    "payment_key" varchar(190) DEFAULT NULL,
    "mode" varchar(40) DEFAULT NULL,
    "note" text,
    "raw_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "completed_at" timestamp without time zone DEFAULT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "payout_methods" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
