    "provider_email" varchar(190) DEFAULT NULL,
    "provider_email_verified" smallint NOT NULL DEFAULT '0',
    "provider_name" varchar(255) DEFAULT NULL,
    "provider_avatar_url" varchar(2048) DEFAULT NULL,
    "linked_at" timestamp without time zone NOT NULL,
