CREATE TABLE "users" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "legacy_source" varchar(40) DEFAULT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "login_name" varchar(64) DEFAULT NULL,
    "email" varchar(190) NOT NULL,
    "phone" varchar(60) DEFAULT NULL,
    "password_hash" varchar(255) NOT NULL,
    "display_name" varchar(190) NOT NULL,
    "status" text NOT NULL DEFAULT 'active' CHECK ("status" IN ('active','inactive','suspended','blocked','pending','pending_author','rejected','deleted')),
    "can_write" smallint NOT NULL DEFAULT '0',
    "talent_enabled" smallint NOT NULL DEFAULT '0',
    "wallet_enabled" smallint NOT NULL DEFAULT '0',
    "payout_enabled" smallint NOT NULL DEFAULT '0',
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    "permissions_updated_at" timestamp without time zone DEFAULT NULL,
    "deleted_at" timestamp without time zone DEFAULT NULL,
    "deleted_by_admin_id" bigint DEFAULT NULL,
    "deletion_mode" text NOT NULL DEFAULT 'none' CHECK ("deletion_mode" IN ('none','anonymized','hard_clean')),
    "anonymized_at" timestamp without time zone DEFAULT NULL,
    "email_verified_at" timestamp without time zone DEFAULT NULL,
    "two_factor_enabled" smallint NOT NULL DEFAULT '0',
    "two_factor_secret" varchar(128) DEFAULT NULL,
    "auth_security_level" varchar(32) NOT NULL DEFAULT 'basic',
    "force_2fa_setup" smallint NOT NULL DEFAULT '0',
    "force_password_change" smallint NOT NULL DEFAULT '0',
    "last_login_at" timestamp without time zone DEFAULT NULL,
    "last_login_ip_hash" varchar(128) DEFAULT NULL,
    "session_version" bigint NOT NULL DEFAULT '0',
    "display_currency" varchar(10) NOT NULL DEFAULT 'AUTO',
    "interface_language" varchar(5) DEFAULT NULL,
    "avatar_path" varchar(255) DEFAULT NULL,
    "avatar_updated_at" timestamp without time zone DEFAULT NULL,
    "article_submit_blocked_until" timestamp without time zone DEFAULT NULL,
    "article_submit_block_reason" text,
    "article_submit_blocked_by" bigint DEFAULT NULL,
    "article_submit_blocked_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_users_email" UNIQUE ("email")
);

CREATE TABLE "wallet_price_packages" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "legacy_source" varchar(80) DEFAULT NULL,
