    "amount_minor" bigint NOT NULL,
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "active" smallint NOT NULL DEFAULT '1',
    "created_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_wallet_price_packages_uq_wallet_price_package" UNIQUE ("points","amount_minor","currency")
);

CREATE TABLE "wallet_topup_packages" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) NOT NULL,
    "name" varchar(128) NOT NULL,
    "description" varchar(255) DEFAULT NULL,
    "amount_minor" bigint NOT NULL,
    "currency" char(3) NOT NULL DEFAULT 'PLN',
    "talent_amount" bigint DEFAULT NULL,
    "is_active" smallint NOT NULL DEFAULT '1',
    "sort_order" integer NOT NULL DEFAULT '0',
    "created_at" timestamp without time zone NOT NULL,
    "updated_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_wallet_topup_packages_code" UNIQUE ("code")
);

CREATE TABLE "wallet_transactions" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "wallet_id" bigint NOT NULL,
    "user_id" bigint NOT NULL,
    "source_module" varchar(40) NOT NULL DEFAULT 'system',
    "type" varchar(80) NOT NULL,
    "account_type" text NOT NULL DEFAULT 'slowo' CHECK ("account_type" IN ('main','slowo','points')),
    "status" text NOT NULL DEFAULT 'posted' CHECK ("status" IN ('pending','posted','reserved','cancelled','failed')),
    "amount_minor" bigint NOT NULL DEFAULT '0',
    "balance_before_minor" bigint NOT NULL DEFAULT '0',
    "points" bigint NOT NULL DEFAULT '0',
    "balance_after_minor" bigint NOT NULL DEFAULT '0',
    "points_after" bigint NOT NULL DEFAULT '0',
    "description" varchar(255) DEFAULT NULL,
    "title_key" varchar(160) DEFAULT NULL,
    "message_key" varchar(160) DEFAULT NULL,
    "description_key" varchar(160) DEFAULT NULL,
    "counterparty_user_id" bigint DEFAULT NULL,
    "ref_type" varchar(80) DEFAULT NULL,
    "ref_id" bigint DEFAULT NULL,
    "legacy_source" varchar(80) DEFAULT NULL,
    "legacy_id" bigint DEFAULT NULL,
    "idempotency_key" varchar(190) DEFAULT NULL,
    "meta_json" jsonb DEFAULT NULL,
    "created_at" timestamp without time zone NOT NULL,
    "previous_hash" varchar(128) DEFAULT NULL,
    "entry_hash" varchar(128) DEFAULT NULL,
    "hash_algorithm" varchar(20) DEFAULT 'hmac-sha256',
    "hash_version" integer DEFAULT '2',
    "signed_at" timestamp without time zone DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_wallet_transactions_uq_wallet_tx_idempotency" UNIQUE ("idempotency_key")
);

CREATE TABLE "wallet_transfers" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
